const storyTemplate = ({ background, earlyCustomers, growth, relationships, currentCustomers, ongoingWork }) => (`[founder's name] opened the company in [year] after several years working in ${background}. Many of the company's earliest customers came through ${earlyCustomers}, but a surprising number continued returning as their needs changed. That repeat business eventually changed the direction of the company from a small early operation into a more established ${growth} business.

The company grew around that original customer base, gradually adding ${relationships}. Because many customers returned over time, the business developed around familiarity with recurring needs rather than isolated one-time requests. As the company became more established locally, it also built a presence through community relationships, local organizations, referrals, and the work it completed in the area.

Today, the company serves ${currentCustomers}, but its beginnings are still part of how it operates. ${ongoingWork} Its local involvement has continued alongside that growth, making the company a familiar part of the market it serves.`);

const createIndustryExample = (profile) => ({
  serviceName: profile.serviceName,
  about: `Business overview:\nWe are a locally operated ${profile.aboutOverview}. We help ${profile.customerDescription} through clear communication, dependable work, and practical guidance.\n\nWhy customers come to us:\nCustomers usually reach out when they need ${profile.customerNeed}. They want to understand the available options, know what the work involves, and have a clear next step.\n\nHow we should be represented:\nSound ${profile.tone}. Explain what is known, identify what needs to be confirmed, and avoid making promises about availability, pricing, or results before the appropriate details are collected.\n\nWhat customers should understand:\n- ${profile.aboutPoints[0]}\n- ${profile.aboutPoints[1]}\n- ${profile.aboutPoints[2]}\n- ${profile.aboutPoints[3]}\n\nService style:\n${profile.serviceStyle}\n\nBoundaries:\n${profile.boundary}`,
  policies: profile.policies.join('\n'),
  faq: profile.faq.reduce((lines, line, index) => {
    if (index > 0 && line.startsWith('Q:')) lines.push('');
    lines.push(line);
    return lines;
  }, []).join('\n'),
  serviceDescription: () => `Service overview:\n${profile.serviceOverview}\n\nBest fit:\n${profile.bestFit}\n\nWhat is included:\n- ${profile.serviceIncludes[0]}\n- ${profile.serviceIncludes[1]}\n- ${profile.serviceIncludes[2]}\n- ${profile.serviceIncludes[3]}\n- ${profile.serviceIncludes[4]}\n\nWhat customers can expect:\n${profile.serviceExpectations}\n\nRecommended next step:\n${profile.recommendedNextStep}`,
});

const createBusinessBriefContext = (profile, industry) => ({
  story: storyTemplate(profile),
  identity: `**Legal business name:** [Legal business name]\n**Doing business as:** [DBA / Trade name, if applicable]\n**Founded:** [Year]\n**Founder:** [Founder's name]\n**Ownership:** [Independent / Family-owned / Partnership / Other]\n**Primary location:** [City, State]\n**Primary market:** [Consumer / Business / Both]`,
  whatWeDo: profile.whatWeDo || `The company operates as ${profile.aboutOverview}. It helps ${profile.customerDescription} with ${profile.customerNeed}. The appropriate approach depends on the customer, the setting, the requested scope, and the information available at the time of the inquiry.`,
  whoWeServe: `The company commonly works with:\n\n${(profile.whoWeServe || [profile.customerDescription, `Customers seeking ${profile.customerNeed}`, 'Local businesses and organizations', 'Referral and repeat customers']).map((item) => `- ${item}`).join('\n')}`,
  serviceArea: `The company primarily serves [primary city/region] and surrounding communities. Its normal operating territory includes [counties, cities, radius, or broader territory].\n\nRequests outside the normal service area may be considered depending on the location, schedule, and scope of the request.`,
  properties: `The company commonly works in or with:\n\n${(profile.properties || [`${industry} appointments, projects, or orders`, 'Customer homes, businesses, or approved work sites', 'The company\'s office, studio, shop, or facility', 'Mobile, scheduled, or remote work settings']).map((item) => `- ${item}`).join('\n')}`,
  howWeWork: profile.howWeWork || `The company first works to understand the customer's situation, the result they need, and the details that affect the available options. It then explains the appropriate path, confirms what is included, and keeps the customer informed about the next step.`,
  operations: profile.operations || `The company operates as [brief description of the operation and the market it serves].\n\n**Team structure:** [Solo / In-house team / Combination]\n**Primary location:** [Location]\n**Operating territory:** [Local / Regional / Multi-state / Other]\n**Operating model:** [By appointment / Scheduled work / Walk-in / Online / Other]`,
  credentials: profile.credentials || `The company maintains the registrations, permits, and professional credentials applicable to the work it performs.\n\n- **[License or registration]:** [Number] — [State / Jurisdiction]\n- **[Certification]:** [Number] — [Issuing organization]\n\n**Professional certifications:** [Certifications, if applicable]\n**Industry affiliations:** [Associations or organizations, if applicable]`,
  additionalContext: profile.additionalContext || `**Insured:** [Yes / No / Details]\n**Languages supported:** [Languages]\n**Customer intake priorities:** [Need, deadline, location, budget, account status, or preferred contact method]\n**Service limitations:** [Work, products, locations, customer types, or situations the company does not support]\n**Priority request triggers:** [Urgencies, deadlines, safety issues, or time-sensitive needs]`,
});

